import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("No Cycle")
        return

    n = int(data[0])

    if n == 0:
        print("No Cycle")
        return

    if len(data) < 1:
        print("No Cycle")
        return

    values = list(map(int, data[1:1+n]))

    if len(data) < 2 + n:
        print("No Cycle")
        return

    pos = int(data[1+n])

    if n <= 0:
        print("No Cycle")
        return

    class Node:
        def __init__(self, val):
            self.val = val
            self.next = None

    nodes = [Node(v) for v in values]

    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i+1]

    if pos >= 0 and pos < len(nodes):
        nodes[-1].next = nodes[pos]

    slow = nodes[0] if nodes else None
    fast = nodes[0] if nodes else None

    has_cycle = False
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            has_cycle = True
            break

    if has_cycle:
        print("Cycle Found")
    else:
        print("No Cycle")

if __name__ == "__main__":
    main()
